import java.io.*;
import java.util.*;
import java.util.stream.IntStream;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new Solver().solve(in, out);
        out.close();
    }

    static class Solver {
        void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            Comb mod = new Comb(n + m);

            long phaseSize = 1;
            long p = 1;
            for (int i = 0; p != 0; i++) {
                p = mod.mult(p, n - i, mod.smallInv(n + m - i));
                phaseSize = mod.add(phaseSize, p);
            }

            long[] answer = {0};
            IntStream.rangeClosed(1, n).forEach(k -> {
                long term = mod.mult(mod.ncr(n, k), m + k, mod.smallInv(k), phaseSize);
                answer[0] = (k & 1) == 1 ? mod.add(answer[0], term) : mod.subtract(answer[0], term);
            });

            out.println(answer[0]);
        }
    }

    static class Comb {
        final long MOD = 998244353L;
        long[] factArr;
        long[] invFactArr;

        Comb(int max) {
            if (max < 0) throw new ArrayIndexOutOfBoundsException(max);
            factArr = new long[max + 1];
            invFactArr = new long[max + 1];
            factArr[0] = 1;
            for (int i = 1; i <= max; i++) {
                factArr[i] = factArr[i - 1] * i % MOD;
            }
            invFactArr[max] = inv(factArr[max]);
            for (int i = max; i >= 1; i--) {
                invFactArr[i - 1] = invFactArr[i] * i % MOD;
            }
        }

        long fact(int n) {
            return factArr[n];
        }

        long fInv(int n) {
            return invFactArr[n];
        }

        long ncr(int n, int r) {
            if (r < 0 || n < r) return 0;
            return mult(fact(n), fInv(r), fInv(n - r));
        }

        long smallInv(int n) {
            return mult(fInv(n), fact(n - 1));
        }

        long add(long a, long b) {
            long v = a + b;
            return v < MOD ? v : v - MOD;
        }

        long subtract(long a, long b) {
            long v = a - b;
            return v < 0 ? v + MOD : v;
        }

        long mult(long... values) {
            long r = 1;
            for (long value : values) {
                r = (r * value) % MOD;
            }
            return r;
        }

        long inv(long value) {
            long g = MOD, x = 0, y = 1;
            for (long r = value; r != 0; ) {
                long q = g / r;
                g %= r;
                long temp = g;
                g = r;
                r = temp;
                x -= q * y;
                temp = x;
                x = y;
                y = temp;
            }
            if (g != 1) throw new AssertionError();
            if (y != MOD && y != -MOD) throw new AssertionError();
            long v = x % MOD;
            if (v < 0) v += MOD;
            return v;
        }
    }

    static class InputReader {
        public final BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
